    "WITH {NC | RR | RS | CS | UR}",
    // - delete:
    "DELETE FROM",
    // - drop table:
    "DROP TABLE",
    // alter table:
    "ALTER TABLE",
    "ADD [COLUMN]",
    "ALTER [COLUMN]",
    "DROP [COLUMN]",
    "SET DATA TYPE",
    // for alter column
    "SET {GENERATED ALWAYS | GENERATED BY DEFAULT}",
    // for alter column
    "SET NOT NULL",
    // for alter column
    "SET {NOT HIDDEN | IMPLICITLY HIDDEN}",
    // for alter column
    "SET FIELDPROC",
    // for alter column
    "DROP {DEFAULT | NOT NULL | GENERATED | IDENTITY | ROW CHANGE TIMESTAMP | FIELDPROC}",
    // for alter column
    // - truncate:
    "TRUNCATE [TABLE]",
    // other
    "SET [CURRENT] SCHEMA",
    "SET CURRENT_SCHEMA",
