    // - create:
    "CREATE [TEMPORARY] [EXTERNAL] TABLE [IF NOT EXISTS]",
    "CREATE [MATERIALIZED] VIEW [IF NOT EXISTS]",
    // - update:
    "UPDATE",
    // - delete:
    "DELETE FROM",
    // - drop table:
    "DROP TABLE [IF EXISTS]",
    // - alter table:
    "ALTER TABLE",
    "RENAME TO",
    // - truncate:
    "TRUNCATE [TABLE]",
    // other
    "ALTER",
    "CREATE",
    "USE",
    "DESCRIBE",
    "DROP",
    "FETCH",
    "SHOW",
    "STORED AS",
    "STORED BY",
    "ROW FORMAT"
