// src/bin/sql-formatter/languages/mariadb/likeMariaDb.ts
function HN(r) {
  return r.map((e, t) => {
    let n = r[t + 1] || ah;
    if (Jd.SET(e) && n.text === "(")
      return { ...e, type: "RESERVED_FUNCTION_NAME" };
    let s = r[t - 1] || ah;
    return Jd.VALUES(e) && s.text === "=" ? { ...e, type: "RESERVED_FUNCTION_NAME" } : e;
  });
}
