// src/bin/sql-formatter/languages/trino/trino.formatter.ts
var UWt, kWt, aPe, FWt, GWt, qWt, qZ, HZ = b(() => {
  Zo();
  nPe();
  oPe();
  UWt = Xe(["SELECT [ALL | DISTINCT]"]), kWt = Xe([
    // queries
    "WITH [RECURSIVE]",
    "FROM",
    "WHERE",
    "GROUP BY [ALL | DISTINCT]",
    "HAVING",
    "WINDOW",
    "PARTITION BY",
    "ORDER BY",
    "LIMIT",
    "OFFSET",
    "FETCH {FIRST | NEXT}",
    // Data manipulation
    // - insert:
    "INSERT INTO",
    "VALUES",
    // - update:
    "SET",
    // MATCH_RECOGNIZE
    "MATCH_RECOGNIZE",
    "MEASURES",
    "ONE ROW PER MATCH",
    "ALL ROWS PER MATCH",
    "AFTER MATCH",
    "PATTERN",
    "SUBSET",
    "DEFINE"
  ]), aPe = Xe([
    // - create:
    "CREATE TABLE [IF NOT EXISTS]",
    "CREATE [OR REPLACE] [MATERIALIZED] VIEW",
    // - update:
    "UPDATE",
    // - delete:
    "DELETE FROM",
    // - drop table:
    "DROP TABLE [IF EXISTS]",
    // - alter table:
    "ALTER TABLE [IF EXISTS]",
    "ADD COLUMN [IF NOT EXISTS]",
    "DROP COLUMN [IF EXISTS]",
    "RENAME COLUMN [IF EXISTS]",
    "RENAME TO",
    "SET AUTHORIZATION [USER | ROLE]",
    "SET PROPERTIES",
    "EXECUTE",
    // - truncate:
    "TRUNCATE TABLE",
    // other
    "ALTER SCHEMA",
    "ALTER MATERIALIZED VIEW",
    "ALTER VIEW",
    "CREATE SCHEMA",
    "CREATE ROLE",
    "DROP SCHEMA",
    "DROP MATERIALIZED VIEW",
    "DROP VIEW",
    "DROP ROLE",
    // Auxiliary
    "EXPLAIN",
    "ANALYZE",
    "EXPLAIN ANALYZE",
    "EXPLAIN ANALYZE VERBOSE",
    "USE",
    "DESCRIBE INPUT",
    "DESCRIBE OUTPUT",
    "REFRESH MATERIALIZED VIEW",
    "RESET SESSION",
    "SET SESSION",
    "SET PATH",
    "SET TIME ZONE",
    "SHOW GRANTS",
    "SHOW CREATE TABLE",
    "SHOW CREATE SCHEMA",
    "SHOW CREATE VIEW",
    "SHOW CREATE MATERIALIZED VIEW",
    "SHOW TABLES",
    "SHOW SCHEMAS",
    "SHOW CATALOGS",
    "SHOW COLUMNS",
    "SHOW STATS FOR",
    "SHOW ROLES",
    "SHOW CURRENT ROLES",
    "SHOW ROLE GRANTS",
    "SHOW FUNCTIONS",
    "SHOW SESSION"
  ]), FWt = Xe([
    "UNION [ALL | DISTINCT]",
    "EXCEPT [ALL | DISTINCT]",
    "INTERSECT [ALL | DISTINCT]"
  ]), GWt = Xe([
    "JOIN",
    "{LEFT | RIGHT | FULL} [OUTER] JOIN",
    "{INNER | CROSS} JOIN",
    "NATURAL [INNER] JOIN",
    "NATURAL {LEFT | RIGHT | FULL} [OUTER] JOIN"
  ]), qWt = Xe([
    "{ROWS | RANGE | GROUPS} BETWEEN",
    // comparison operator
    "IS [NOT] DISTINCT FROM"
  ]), qZ = {
    name: "trino",
    tokenizerOptions: {
      reservedSelect: UWt,
      reservedClauses: [...kWt, ...aPe],
      reservedSetOperations: FWt,
      reservedJoins: GWt,
      reservedPhrases: qWt,
      reservedKeywords: iPe,
      reservedDataTypes: sPe,
      reservedFunctionNames: rPe,
      // Trino also supports {- ... -} parenthesis.
      // The formatting of these currently works out as a result of { and -
      // not getting a space added in-between.
      // https://trino.io/docs/current/sql/match-recognize.html#row-pattern-syntax
      extraParens: ["[]", "{}"],
      // https://trino.io/docs/current/language/types.html#string
      // https://trino.io/docs/current/language/types.html#varbinary
      stringTypes: [
        { quote: "''-qq", prefixes: ["U&"] },
        { quote: "''-raw", prefixes: ["X"], requirePrefix: !0 }
      ],
      // https://trino.io/docs/current/language/reserved.html
      identTypes: ['""-qq'],
      paramTypes: { positional: !0 },
      operators: [
        "%",
        "->",
        "=>",
        ":",
        "||",
        // Row pattern syntax
        "|",
        "^",
        "$"
        // '?', conflicts with positional placeholders
      ]
    },
    formatOptions: {
      onelineClauses: aPe
    }
  };
});

